required<-c("survival","dplyr","ggplot2","readr","broom");missing<-required[!vapply(required,requireNamespace,logical(1),quietly=TRUE)];if(length(missing))stop("Missing packages: ",paste(missing,collapse=", "))
suppressPackageStartupMessages({library(survival);library(dplyr);library(ggplot2);library(readr);library(broom)})
dir.create("results/tables",recursive=TRUE,showWarnings=FALSE);dir.create("results/figures",recursive=TRUE,showWarnings=FALSE);set.seed(3404)
n<-500;covid<-tibble(age=round(runif(n,18,92)),male=rbinom(n,1,.48),comorbidity=rbinom(n,1,.35),vaccinated=rbinom(n,1,.7)) %>% mutate(severe=rbinom(n,1,plogis(-5+.045*age+.55*male+1.05*comorbidity-.9*vaccinated)));m1<-glm(severe~age+male+comorbidity+vaccinated,covid,family=binomial());forest<-tidy(m1,conf.int=TRUE,exponentiate=TRUE)%>%filter(term!="(Intercept)");write_csv(forest,"results/tables/covid_severity_odds_ratios.csv");p<-ggplot(forest,aes(estimate,reorder(term,estimate)))+geom_vline(xintercept=1,linetype=2,color="grey50")+geom_errorbar(aes(xmin=conf.low,xmax=conf.high),width=.18,color="#28666E",orientation="y")+geom_point(size=3,color="#B24C63")+scale_x_log10()+labs(title="Factors associated with severe COVID-19",subtitle="Adjusted odds ratios with 95% confidence intervals",x="Odds ratio (log scale)",y=NULL,caption="Synthetic case study; associations are not causal effects.")+theme_minimal(base_size=12);ggsave("results/figures/covid_severity_forest.png",p,width=8,height=5,dpi=240,bg="white")
trial<-tibble(treatment=factor(rep(c("Control","Treatment A","Treatment B"),each=55)),reduction=c(rnorm(55,5,2),rnorm(55,7,2),rnorm(55,8.5,2)));m2<-aov(reduction~treatment,trial);write_csv(tidy(m2),"results/tables/trial_anova.csv");write_csv(tidy(TukeyHSD(m2)),"results/tables/trial_tukey.csv")
n<-190;onc<-tibble(treatment=factor(sample(c("Standard","New"),n,TRUE)),age=round(runif(n,35,85)),stage=factor(sample(c("II","III","IV"),n,TRUE,prob=c(.25,.45,.3)))) %>% mutate(rate=exp(-3.2-.3*(treatment=="New")+.02*(age-55)+.45*(stage=="III")+.9*(stage=="IV")),event_time=rexp(n,rate),censor=runif(n,4,22),time=pmin(event_time,censor),status=as.integer(event_time<=censor));km<-survfit(Surv(time,status)~treatment,onc);m3<-coxph(Surv(time,status)~treatment+age+stage,onc);write_csv(tidy(m3,conf.int=TRUE,exponentiate=TRUE),"results/tables/oncology_cox.csv");zph<-cox.zph(m3);zph_table<-data.frame(term=rownames(zph$table),zph$table,row.names=NULL,check.names=FALSE);write_csv(zph_table,"results/tables/oncology_ph_diagnostic.csv");png("results/figures/oncology_kaplan_meier.png",1800,1300,res=220);plot(km,col=c("#B24C63","#28666E"),lwd=3,xlab="Follow-up time",ylab="Survival probability",main="Oncology case: Kaplan–Meier curves");legend("bottomleft",levels(onc$treatment),col=c("#B24C63","#28666E"),lwd=3,bty="n");dev.off();cat("Applied cases complete: COVID logistic/forest, trial ANOVA/Tukey, oncology KM/Cox.\n")
